-- Update only the original bundled descriptions, preserving custom edits.
UPDATE worlds SET description = 'An icy night aboard the Titanic. Your younger sibling is missing below deck as the lifeboats begin to fill. Find them and choose whom you can help before the last boat leaves.' WHERE id = 'titanic-adventure' AND title = 'The Titanic' AND description LIKE 'Titanic, directed by James Cameron%';
UPDATE worlds SET description = 'A stranger on a night train confesses to a terrible act. His story contradicts a letter you found in the carriage. Uncover what happened before the next station, where someone is waiting for him.' WHERE id = 'the-kreutzer-sonata' AND title = 'The Kreutzer Sonata' AND description LIKE 'The Kreutzer Sonata is a chilling%';
UPDATE worlds SET description = 'The bridge closes at dawn. You are driving an ambulance through a retreat on the Italian front, carrying a wounded friend and a letter that could get you both across the border. Decide what you are willing to risk.' WHERE id = 'a-farewell-to-arms' AND title = 'A Farewell to Arms' AND description LIKE 'A Farewell to Arms is a deeply%';
UPDATE worlds SET description = 'A borrowed time machine disappears in Quahog on the morning of the town parade. You promised to return it by noon. Follow a trail of absurd mishaps before someone accidentally rewrites the town.' WHERE id = 'family-guy' AND title = 'Family Guy' AND description LIKE 'Family Guy is a long-running%';
